public RenewalOrder(String memberId,
                    String externalTxnId,
                    int months,
                    long originalAmountCents,
                    long discountCents,
                    int discountPercent,
                    String couponCode,
                    long amountCents,
                    LocalDateTime paidAt) {
    this.id = UUID.randomUUID().toString();
    this.memberId = Objects.requireNonNull(memberId);
    this.externalTxnId = Objects.requireNonNull(externalTxnId);
    this.months = months;
    if (originalAmountCents - discountCents != amountCents) {
        throw new IllegalArgumentException("originalAmountCents - discountCents must equal amountCents");
