package com.acme.member.renewal;

import com.acme.member.coupon.Coupon;
import com.acme.member.coupon.CouponRepository;
import com.acme.member.member.MemberService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;

/**
 * 续费回调处理。
 *
 * <p>规则：验签失败拒绝；同一支付流水号只处理一次（幂等）；处理成功只顺延一次到期日。
 * 券码可选：有券时按券面百分比计算优惠分与实付分，并在落单前完成全部校验。
 */
@Service
public class RenewalService {

    private final RenewalRepository renewalRepository;
    private final MemberService memberService;
    private final SignatureVerifier signatureVerifier;
    private final CouponRepository couponRepository;
    private final Clock clock;
    private final ZoneId zoneId;

    @Autowired
    public RenewalService(RenewalRepository renewalRepository,
                          MemberService memberService,
                          SignatureVerifier signatureVerifier,
                          Clock clock,
                          @Value("${renewal.timezone:Asia/Shanghai}") String zoneId) {
        this(renewalRepository, memberService, signatureVerifier, clock, ZoneId.of(zoneId), new CouponRepository());
    }

    RenewalService(RenewalRepository renewalRepository,
                   MemberService memberService,
                   SignatureVerifier signatureVerifier,
                   Clock clock,
                   ZoneId zoneId) {
        this(renewalRepository, memberService, signatureVerifier, clock, zoneId, new CouponRepository());
    }

    RenewalService(RenewalRepository renewalRepository,
                   MemberService memberService,
                   SignatureVerifier signatureVerifier,
                   Clock clock,
                   ZoneId zoneId,
                   CouponRepository couponRepository) {
        this.renewalRepository = renewalRepository;
        this.memberService = memberService;
        this.signatureVerifier = signatureVerifier;
        this.couponRepository = couponRepository;
        this.clock = clock;
        this.zoneId = zoneId;
    }

    public CallbackResult handleCallback(CallbackCommand command) {
        if (!signatureVerifier.verify(command.externalTxnId(), command.amountCents(), command.signature())) {
            throw new InvalidSignatureException();
        }
        // 幂等：同一流水号直接返回已处理，不再顺延到期日，也不再计算优惠。
        return renewalRepository.findByExternalTxnId(command.externalTxnId())
                .map(existing -> new CallbackResult(true, existing))
                .orElseGet(() -> process(command));
    }

    private CallbackResult process(CallbackCommand command) {
        memberService.getMember(command.memberId());
        LocalDateTime paidAt = LocalDateTime.now(clock.withZone(zoneId));
        CouponApplication coupon = applyCoupon(command, paidAt);

        RenewalOrder order = new RenewalOrder(
                command.memberId(),
                command.externalTxnId(),
                command.months(),
                coupon.originalAmountCents(),
                coupon.discountCents(),
                coupon.discountPercent(),
                coupon.couponCode(),
                command.amountCents(),
                paidAt
        );
        renewalRepository.save(order);
        memberService.renew(command.memberId(), command.months());
        return new CallbackResult(false, order);
    }

    /**
     * 券计算（纯函数）：无券保持原价；有券时校验存在性、有效期、原价与折后金额。
     * 所有校验都在落单/顺延之前完成，失败不占用 externalTxnId。
     */
    private CouponApplication applyCoupon(CallbackCommand command, LocalDateTime paidAt) {
        String rawCouponCode = command.couponCode();
        if (rawCouponCode == null || rawCouponCode.isBlank()) {
            return new CouponApplication(command.amountCents(), 0L, 0, "", command.amountCents());
        }

        Long originalAmountCents = command.originalAmountCents();
        if (originalAmountCents == null || originalAmountCents <= 0) {
            throw new CouponValidationException("使用券码时 originalAmountCents 必填且必须为正数");
        }

        Coupon coupon = couponRepository.findByCode(rawCouponCode)
                .filter(candidate -> candidate.isValidAt(paidAt))
                .orElseThrow(() -> new CouponValidationException(
                        "券码不存在、未生效、已过期或已停用: " + rawCouponCode.trim()));

        long discountCents = coupon.discountCents(originalAmountCents);
        long payableCents = coupon.payableCents(originalAmountCents);
        if (payableCents != command.amountCents()) {
            throw new CouponValidationException(
                    "折后金额与 amountCents 不一致: originalAmountCents=" + originalAmountCents
                            + ", discountCents=" + discountCents
                            + ", payableCents=" + payableCents
                            + ", amountCents=" + command.amountCents());
        }
        return new CouponApplication(
                originalAmountCents,
                discountCents,
                coupon.getDiscountPercent(),
                coupon.getCode(),
                payableCents);
    }

    public boolean verifySignature(String externalTxnId, long amountCents, String signature) {
        return signatureVerifier.verify(externalTxnId, amountCents, signature);
    }

    /** 回调命令。couponCode/originalAmountCents 为可选字段，旧五参数入口保持兼容。 */
    public record CallbackCommand(String externalTxnId,
                                  String memberId,
                                  int months,
                                  long amountCents,
                                  String signature,
                                  String couponCode,
                                  Long originalAmountCents) {

        public CallbackCommand(String externalTxnId, String memberId, int months, long amountCents, String signature) {
            this(externalTxnId, memberId, months, amountCents, signature, null, null);
        }
    }

    /** 处理结果：duplicate 表示命中幂等。 */
    public record CallbackResult(boolean duplicate, RenewalOrder order) {
    }

    private record CouponApplication(long originalAmountCents,
                                     long discountCents,
                                     int discountPercent,
                                     String couponCode,
                                     long payableCents) {
    }

    public static class InvalidSignatureException extends RuntimeException {
        public InvalidSignatureException() {
            super("回调签名校验失败");
        }
    }

    public static class CouponValidationException extends RuntimeException {
        public CouponValidationException(String message) {
            super(message);
        }
    }
}

package com.acme.member.renewal;

import com.acme.member.member.MemberService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/renewal")
public class RenewalController {

    private final RenewalService renewalService;
    private final RenewalRepository renewalRepository;

    public RenewalController(RenewalService renewalService, RenewalRepository renewalRepository) {
        this.renewalService = renewalService;
        this.renewalRepository = renewalRepository;
    }

    @PostMapping("/callback")
    public ResponseEntity<Map<String, Object>> callback(@RequestBody CallbackRequest request) {
        try {
            RenewalService.CallbackResult result = renewalService.handleCallback(new RenewalService.CallbackCommand(
                    request.externalTxnId(),
                    request.memberId(),
                    request.months(),
                    request.amountCents(),
                    request.signature(),
                    request.couponCode(),
                    request.originalAmountCents()
            ));
            return ResponseEntity.ok(Map.of(
                    "code", 0,
                    "duplicate", result.duplicate(),
                    "orderId", result.order().getId()
            ));
        } catch (RenewalService.InvalidSignatureException exception) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("code", 401, "error", "签名校验失败"));
        } catch (MemberService.MemberNotFoundException exception) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Map.of("code", 404, "error", "会员不存在"));
        } catch (RenewalService.CouponValidationException exception) {
            return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                    .body(Map.of("code", 400, "error", exception.getMessage()));
        }
    }

    @GetMapping("/orders")
    public List<Map<String, Object>> orders() {
        return renewalRepository.findAll().stream()
                .map(order -> Map.<String, Object>of(
                        "id", order.getId(),
                        "memberId", order.getMemberId(),
                        "externalTxnId", order.getExternalTxnId(),
                        "months", order.getMonths(),
                        "originalAmountCents", order.getOriginalAmountCents(),
                        "discountCents", order.getDiscountCents(),
                        "discountPercent", order.getDiscountPercent(),
                        "couponCode", order.getCouponCode(),
                        "amountCents", order.getAmountCents(),
                        "status", order.getStatus().name()
                ))
                .toList();
    }

    /** 回调请求；couponCode/originalAmountCents 可选，旧五字段入口保持兼容。 */
    public record CallbackRequest(String externalTxnId,
                                  String memberId,
                                  int months,
                                  long amountCents,
                                  String signature,
                                  String couponCode,
                                  Long originalAmountCents) {

        public CallbackRequest(String externalTxnId, String memberId, int months, long amountCents, String signature) {
            this(externalTxnId, memberId, months, amountCents, signature, null, null);
        }
    }
}

