}

public RenewalOrder(String memberId,
                    String externalTxnId,
                    int months,
                    long originalAmountCents,
                    long discountCents,
                    int discountPercent,
                    String couponCode,
                    long amountCents,
                    LocalDateTime paidAt) {
    this.id = UUID.randomUUID().toString();
    this.memberId = Objects.requireNonNull(memberId);
    this.externalTxnId = Objects.requireNonNull(externalTxnId);
    this.months = months;
    if (originalAmountCents - discountCents != amountCents) {
        throw new IllegalArgumentException("originalAmountCents - discountCents must equal amountCents");
    }
    if (discountCents < 0) {
        throw new IllegalArgumentException("discountCents must not be negative");
    }
    this.originalAmountCents = originalAmountCents;
    this.discountCents = discountCents;
    this.discountPercent = discountPercent;
    this.couponCode = couponCode == null ? "" : couponCode;
    this.amountCents = amountCents;
    this.status = Status.PAID;
    this.paidAt = Objects.requireNonNull(paidAt);
}

