public ResponseEntity<Map<String, Object>> quote(@RequestBody QuoteRequest request) {
    try {
        RenewalService.QuoteResult result = renewalService.quote(new RenewalService.QuoteCommand(
                request.memberId(),
                request.months(),
                request.originalAmountCents(),
                request.couponCode()
        ));
        return ResponseEntity.ok(Map.of(
                "originalAmountCents", result.originalAmountCents(),
                "discountCents", result.discountCents(),
                "payableAmountCents", result.payableAmountCents(),
                "couponCode", result.couponCode(),
                "discountPercent", result.discountPercent()
        ));
    } catch (MemberService.MemberNotFoundException exception) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(Map.of("code", 404, "error", "会员不存在"));
    } catch (RenewalService.CouponValidationException exception) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(Map.of("code", 400, "error", exception.getMessage()));
    }
}

